// Package pricedata embeds the default AWS price snapshot in the binary.
//
// The snapshot (aws-prices.json) is generated by cmd/pricegen and must not be
// edited by hand: aws-prices.json.sha256 records its digest, and both
// VerifyEmbedded and this package's tests reject a mismatch. It lives in its
// own package so that pricegen, which writes the file, does not depend on it.
package pricedata

import (
	"bytes"
	"embed"
	"sync"

	"github.com/guneshm03/planprice/internal/pricing"
)

//go:embed aws-prices.json aws-prices.json.sha256
var files embed.FS

const (
	snapshotFile = "aws-prices.json"
	checksumFile = "aws-prices.json.sha256"
)

var (
	once sync.Once
	snap *pricing.Snapshot
	err  error
)

// Default returns the embedded snapshot. It is decoded once and shared;
// callers must not modify it.
func Default() (*pricing.Snapshot, error) {
	once.Do(func() {
		var data []byte
		data, err = files.ReadFile(snapshotFile)
		if err != nil {
			return
		}
		snap, err = pricing.Load(bytes.NewReader(data))
	})
	return snap, err
}

// VerifyEmbedded checks the embedded snapshot against its checksum file and
// returns the hex digest.
func VerifyEmbedded() (string, error) {
	data, err := files.ReadFile(snapshotFile)
	if err != nil {
		return "", err
	}
	sum, err := files.ReadFile(checksumFile)
	if err != nil {
		return "", err
	}
	if err := pricing.VerifyChecksum(data, sum); err != nil {
		return "", err
	}
	return pricing.Digest(data), nil
}
